/* Base styles */
html {
  font-size: 14px;
}

@media (min-width: 768px) {
  html {
    font-size: 16px;
  }
}

.btn:focus, .btn:active:focus, .btn-link.nav-link:focus, .form-control:focus, .form-check-input:focus {
  box-shadow: 0 0 0 0.1rem white, 0 0 0 0.25rem #258cfb;
}

html {
  position: relative;
  min-height: 100%;
}

body {
  margin-bottom: 60px;
}

/* eShop specific styles */
.esh-table {
  margin: 20px 0;
}

.esh-link-wrapper {
  text-align: right;
  margin-bottom: 20px;
}

.esh-button {
  padding: 8px 16px;
  text-decoration: none;
  border-radius: 4px;
  display: inline-block;
  font-weight: 500;
}

.esh-button-primary {
  background-color: #007bff;
  color: white;
  border: 1px solid #007bff;
}

.esh-button-primary:hover {
  background-color: #0056b3;
  border-color: #0056b3;
  color: white;
  text-decoration: none;
}

.esh-table-header {
  background-color: #f8f9fa;
  font-weight: 600;
}

.esh-table-link {
  color: #007bff;
  text-decoration: none;
  margin: 0 2px;
}

.esh-table-link:hover {
  color: #0056b3;
  text-decoration: underline;
}

.esh-thumbnail {
  max-width: 60px;
  max-height: 60px;
  border-radius: 4px;
}

.esh-price {
  font-weight: 600;
  color: #28a745;
}

/* Header styles */
.esh-header-brand {
  padding: 10px 20px;
}

.esh-header-brand img {
  max-height: 40px;
}

.esh-app-hero {
  background-color: #f8f9fa;
  padding: 40px 0;
  margin-bottom: 30px;
}

.esh-header {
  text-align: center;
}

.esh-header-title {
  font-size: 2.5rem;
  font-weight: 300;
  color: #343a40;
  margin: 0;
}

.esh-header-title span {
  color: #6c757d;
  font-size: 1.5rem;
}

/* Footer styles */
.esh-app-footer {
  background-color: #343a40;
  padding: 40px 0;
  margin-top: 60px;
  color: white;
}

.esh-app-footer-brand {
  max-height: 60px;
}

.esh-app-footer-text {
  margin-bottom: 10px;
}

/* Pagination styles */
.esh-pager {
  margin-top: 30px;
  padding: 20px 0;
}

.esh-pager-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
}

.esh-pager-wrapper nav {
  display: flex;
  align-items: center;
  gap: 20px;
}

.esh-pager-item {
  padding: 8px 12px;
  text-decoration: none;
  border-radius: 4px;
  color: #495057;
}

.esh-pager-item--navigable {
  background-color: #f8f9fa;
  border: 1px solid #dee2e6;
  color: #007bff;
}

.esh-pager-item--navigable:hover {
  background-color: #e9ecef;
  color: #0056b3;
  text-decoration: none;
}

.esh-pager-item--hidden {
  visibility: hidden;
}

/* Form styles */
.form-group {
  margin-bottom: 1rem;
}

.form-label {
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.form-control:focus {
  border-color: #007bff;
  box-shadow: 0 0 0 0.2rem rgba(0, 123, 255, 0.25);
}

.btn-secondary {
  background-color: #6c757d;
  border-color: #6c757d;
}

.btn-secondary:hover {
  background-color: #545b62;
  border-color: #545b62;
}

.btn-danger {
  background-color: #dc3545;
  border-color: #dc3545;
}

.btn-danger:hover {
  background-color: #c82333;
  border-color: #bd2130;
}

/* Validation styles */
.field-validation-error {
  color: #dc3545;
  font-size: 0.875em;
  margin-top: 0.25rem;
}

.validation-summary-errors {
  color: #dc3545;
  background-color: #f8d7da;
  border: 1px solid #f5c6cb;
  border-radius: 0.25rem;
  padding: 0.75rem 1.25rem;
  margin-bottom: 1rem;
}

.validation-summary-errors ul {
  margin: 0;
  padding-left: 1.25rem;
}

.input-validation-error {
  border-color: #dc3545;
}

/* Responsive utilities */
@media (max-width: 576px) {
  .esh-header-title {
    font-size: 2rem;
  }

  .esh-header-title span {
    font-size: 1.2rem;
    display: block;
    margin-top: 0.5rem;
  }

  .esh-pager-wrapper nav {
    flex-direction: column;
    gap: 10px;
  }

  .table-responsive {
    font-size: 0.875rem;
  }
}

/* Card styles for forms */
.card {
  border: 1px solid #dee2e6;
  border-radius: 0.375rem;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
}

.card-header {
  background-color: #f8f9fa;
  border-bottom: 1px solid #dee2e6;
  padding: 1rem 1.25rem;
  font-weight: 600;
}

.card-body {
  padding: 1.25rem;
}

/* Alert styles */
.alert {
  border-radius: 0.375rem;
  margin-bottom: 1rem;
}

.alert-success {
  color: #155724;
  background-color: #d4edda;
  border-color: #c3e6cb;
}

.alert-danger {
  color: #721c24;
  background-color: #f8d7da;
  border-color: #f5c6cb;
}

.alert-info {
  color: #0c5460;
  background-color: #d1ecf1;
  border-color: #bee5eb;
}

