    /// <summary>
    /// Creates a new catalog item asynchronously
    /// </summary>
    /// <param name="catalogItemCreateDto">The catalog item creation DTO</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>The created catalog item DTO</returns>
    Task<CatalogItemDto> CreateAsync(CatalogItemCreateDto catalogItemCreateDto, CancellationToken cancellationToken = default);

    /// <summary>
    /// Updates an existing catalog item asynchronously
    /// </summary>
    /// <param name="id">The catalog item identifier</param>
    /// <param name="catalogItemUpdateDto">The catalog item update DTO</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>The updated catalog item DTO</returns>
    Task<CatalogItemDto?> UpdateAsync(int id, CatalogItemUpdateDto catalogItemUpdateDto, CancellationToken cancellationToken = default);

    /// <summary>
    /// Deletes a catalog item by identifier asynchronously
    /// </summary>
    /// <param name="id">The catalog item identifier</param>
    /// <param name="cancellationToken">Cancellation token</param>
    /// <returns>True if deleted successfully, otherwise false</returns>
